import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        char[] s = next().toCharArray();
        long[] counts = new long[26], chosen = new long[26];
        long missing = 0;
        for (char c : s) {
            if (c == '?') missing++;
            else counts[c - 'a']++;
        }
        // Min-heap on (count, letter): each new copy costs the letter's current count.
        PriorityQueue<long[]> heap = new PriorityQueue<>((x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));
        for (int i = 0; i < 26; i++) heap.add(new long[] {counts[i], i});
        for (long t = 0; t < missing; t++) {
            long[] top = heap.poll();
            chosen[(int) top[1]]++;
            heap.add(new long[] {top[0] + 1, top[1]});
        }
        // Place the chosen letters in ascending order into the question marks from left to right.
        int letter = 0;
        for (int i = 0; i < s.length; i++) {
            if (s[i] != '?') continue;
            while (chosen[letter] == 0) letter++;
            s[i] = (char) ('a' + letter);
            chosen[letter]--;
        }
        System.out.println(new String(s));
    }
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func next() string {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

type entry struct{ count, letter int }
type minHeap []entry

func (h minHeap) Len() int { return len(h) }
func (h minHeap) Less(i, j int) bool {
	if h[i].count != h[j].count {
		return h[i].count < h[j].count
	}
	return h[i].letter < h[j].letter
}
func (h minHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)   { *h = append(*h, x.(entry)) }
func (h *minHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	s := []byte(next())
	var counts, chosen [26]int
	missing := 0
	for _, c := range s {
		if c == '?' {
			missing++
		} else {
			counts[c-'a']++
		}
	}
	// Min-heap on (count, letter): each new copy costs the letter's current count.
	h := &minHeap{}
	for i := 0; i < 26; i++ {
		*h = append(*h, entry{counts[i], i})
	}
	heap.Init(h)
	for t := 0; t < missing; t++ {
		top := heap.Pop(h).(entry)
		chosen[top.letter]++
		heap.Push(h, entry{top.count + 1, top.letter})
	}
	// Place the chosen letters in ascending order into the question marks from left to right.
	letter := 0
	for i := range s {
		if s[i] != '?' {
			continue
		}
		for chosen[letter] == 0 {
			letter++
		}
		s[i] = byte('a' + letter)
		chosen[letter]--
	}
	fmt.Println(string(s))
}
